Evaluate the JavaScript procedural FPS map generator implementation. 

Solution A: function generateMap(canvasId){const canvas=document.getElementById(canvasId);if(!canvas)return;const ctx=canvas.getContext('2d');const tileSize=10;const size=50;let map=Array.from({length:size},()=>Array(size).fill(0));for(let i=0;i<size;i++){map[0][i]=0;map[size-1][i]=0;map[i][0]=0;map[i][size-1]=0;}const rooms=[];const roomCount=Math.floor(Math.random()*4)+5;for(let i=0;i<roomCount;i++){const w=Math.floor(Math.random()*6)+5;const h=Math.floor(Math.random()*6)+5;const x=Math.floor(Math.random()*(size-2-w))+1;const y=Math.floor(Math.random()*(size-2-h))+1;for(let r=x;r<x+w;r++){for(let c=y;c<y+h;c++){map[r][c]=1;}}rooms.push({x:Math.floor(x+w/2),y:Math.floor(y+h/2)});}for(let i=0;i<rooms.length-1;i++){const a=rooms[i];const b=rooms[i+1];let cx=a.x,cy=a.y;while(cx!==b.x){map[cx][cy]=1;cx+=b.x>cx?1:-1;}while(cy!==b.y){map[cx][cy]=1;cy+=b.y>cy?1:-1;}}function flood(){const visited=Array.from({length:size},()=>Array(size).fill(false));let start=null;for(let i=0;i<size&&!start;i++){for(let j=0;j<size&& !start;j++){if(map[i][j]===1){start=[i,j];}}}if(!start)return{reachable:false,visited};const queue=[start];let head=0;visited[start[0]][start[1]]=true;let count=0;while(head<queue.length){const [x,y]=queue[head++];if(map[x][y]!==1)continue;count++;if(x>0&&!visited[x-1][y]){visited[x-1][y]=true;queue.push([x-1,y]);}if(x<size-1&&!visited[x+1][y]){visited[x+1][y]=true;queue.push([x+1,y]);}if(y>0&&!visited[x][y-1]){visited[x][y-1]=true;queue.push([x,y-1]);}if(y<size-1&&!visited[x][y+1]){visited[x][y+1]=true;queue.push([x,y+1]);}}const totalFloor=map.flat().filter(v=>v===1).length;return{reachable:count===totalFloor,visited};}let floodResult=flood();while(!floodResult.reachable){map=Array.from({length:size},()=>Array(size).fill(0));for(let i=0;i<size;i++){map[0][i]=0;map[size-1][i]=0;map[i][0]=0;map[i][size-1]=0;}}const visited=floodResult.visited;const floorSites=[];for(let i=0;i<size;i++){for(let j=0;j<size;j++){if(map[i][j]===1&&visited[i][j])floorSites.push([i,j]);}}let spawnPoints=[];if(floorSites.length>=2){const first=floorSites[Math.floor(Math.random()*floorSites.length)];spawnPoints.push(first);let far=first,maxD=-1;for(const [x,y] of floorSites){const d=Math.abs(x-first[0])+Math.abs(y-first[1]);if(d>maxD){maxD=d;far=[x,y];}}spawnPoints.push(far);}const pickCount=Math.floor(Math.random()*3)+3;const pickups=[];const available=floorSites.filter(([x,y])=>!spawnPoints.some(sp=>sp[0]===x&&sp[1]===y));for(let i=0;i<pickCount&&available.length;i++){const idx=Math.floor(Math.random()*available.length);pickups.push(available[idx]);available.splice(idx,1);}}ctx.clearRect(0,0,canvas.width,canvas.height);for(let i=0;i<size;i++){for(let j=0;j<size;j++){ctx.fillStyle=map[i][j]===1?'gray':'black';ctx.fillRect(i*tileSize,j*tileSize,tileSize,tileSize);}}ctx.fillStyle='green';for(const [x,y] of spawnPoints){ctx.fillRect(x*tileSize,y*tileSize,tileSize,tileSize);}ctx.fillStyle='red';for(const [x,y] of pickups){ctx.fillRect(x*tileSize,y*tileSize,tileSize,tileSize);}const legendX=10,legendY=10;const legendBg='rgba(255,255,255,0.8)';ctx.fillStyle=legendBg;ctx.fillRect(legendX-2,legendY-2,120,80);ctx.fillStyle='black';ctx.font='12px Arial';ctx.fillText('Legend',legendX,legendY+12);const entries=[['Walls','black'],['Floor','gray'],['Spawn','green'],['Weapon','red']];let line=legendY+25;for(const [label,color] of entries){ctx.fillStyle=color;ctx.fillRect(legendX,line,15,15);ctx.fillStyle='black';ctx.fillText(label,legendX+20,line+12);line+=20;}let btn=document.getElementById('generateBtn');if(!btn){btn=document.createElement('button');btn.id='generateBtn';btn.innerText='Generate New Map';btn.style.position='absolute';btn.style.top=(canvas.offsetTop+canvas.height+10)+'px';btn.style.left=canvas.offsetLeft+'px';document.body.appendChild(btn);btn.onclick=()=>generateMap(canvasId);}}

Solution B: function generateFPSMap(canvasId){
    const MAP_CELLS = 50;
    const CELL_SIZE = 10;
    const MAX_SPLIT_DEPTH = 4;
    const MIN_ROOM_SIZE = 5;
    const MAX_ROOM_SIZE = 12;
    const SPAWN_COUNT = 2;
    const WEAPON_COUNT = 3;
    const MAX_ATTEMPTS = 5;
    const canvas = document.getElementById(canvasId);
    if(!canvas)return;
    canvas.width=canvas.height=MAP_CELLS*CELL_SIZE;
    const ctx = canvas.getContext('2d');

    // ----- helper classes -----
    class Rect{constructor(x,y,w,h){this.x=x;this.y=y;this.w=w;this.h=h;}}
    function randInt(min,max){return Math.floor(Math.random()*(max-min+1))+min;}
    function splitRect(rect,depth){
        if(depth===0||rect.w<MIN_ROOM_SIZE*2||rect.h<MIN_ROOM_SIZE*2)return [rect];
        const splitVert = rect.w>rect.h;
        const max = (splitVert?rect.w:rect.h)-MIN_ROOM_SIZE*2;
        if(max<=MIN_ROOM_SIZE)return [rect];
        const splitPos = randInt(MIN_ROOM_SIZE, max);
        let r1,r2;
        if(splitVert){
            r1=new Rect(rect.x,rect.y,splitPos,rect.h);
            r2=new Rect(rect.x+splitPos,rect.y,rect.w-splitPos,rect.h);
        }else{
            r1=new Rect(rect.x,rect.y,rect.w,splitPos);
            r2=new Rect(rect.x,rect.y+splitPos,rect.w,rect.h-splitPos);
        }
        return [...splitRect(r1,depth-1),...splitRect(r2,depth-1)];
    }
    function createRooms(leaves){
        const rooms=[];
        leaves.forEach(leaf=>{
            const w=randInt(MIN_ROOM_SIZE,Math.min(MAX_ROOM_SIZE,leaf.w-2));
            const h=randInt(MIN_ROOM_SIZE,Math.min(MAX_ROOM_SIZE,leaf.h-2));
            const x=randInt(leaf.x+1, leaf.x+leaf.w-w-1);
            const y=randInt(leaf.y+1, leaf.y+leaf.h-h-1);
            rooms.push(new Rect(x,y,w,h));
        });
        return rooms;
    }
    function carve(map,rect){
        for(let i=rect.x;i<rect.x+rect.w;i++){
            for(let j=rect.y;j<rect.y+rect.h;j++){
                map[i][j]=1; // floor
            }
        }
    }
    function carveCorridor(map,x1,y1,x2,y2){
        let x=x1, y=y1;
        while(x!==x2){
            map[x][y]=1;
            x+=x<x2?1:-1;
        }
        while(y!==y2){
            map[x][y]=1;
            y+=y<y2?1:-1;
        }
    }
    function distance(c1,c2){
        const dx=c1.x-c2.x, dy=c1.y-c2.y;
        return Math.sqrt(dx*dx+dy*dy);
    }
    function floodFill(map,startX,startY){
        const visited=Array.from({length:MAP_CELLS},()=>Array(MAP_CELLS).fill(false));
        const queue=[[startX,startY]];
        visited[startX][startY]=true;
        const dirs=[[1,0],[-1,0],[0,1],[0,-1]];
        let count=0;
        while(queue.length){
            const [x,y]=queue.shift(); count++;
            for(const [dx,dy] of dirs){
                const nx=x+dx, ny=y+dy;
                if(nx>=0&&nx<MAP_CELLS&&ny>=0&&ny<MAP_CELLS && map[nx][ny]===1 && !visited[nx][ny]){
                    visited[nx][ny]=true;
                    queue.push([nx,ny]);
                }
            }
        }
        return visited;
    }

    // ----- generation loop -----
    let attempt=0;
    let map, rooms, spawnPoints, weaponPoints;
    while(attempt<MAX_ATTEMPTS){
        // init map
        map=Array.from({length:MAP_CELLS},()=>Array(MAP_CELLS).fill(0));
        // BSP split
        const leaves=splitRect(new Rect(0,0,MAP_CELLS,MAP_CELLS),MAX_SPLIT_DEPTH);
        // rooms
        rooms=createRooms(leaves);
        rooms.forEach(r=>carve(map,r));
        // corridors by connecting room centers
        const centers=rooms.map(r=>({x:Math.floor(r.x+r.w/2),y:Math.floor(r.y+r.h/2)}));
        for(let i=1;i<centers.length;i++){
            const a=centers[i-1], b=centers[i];
            carveCorridor(map,a.x,a.y,b.x,b.y);
        }
        // spawn points (choose farthest rooms)
        let maxDist= -1, pair=[0,1];
        for(let i=0;i<centers.length;i++){
            for(let j=i+1;j<centers.length;j++){
                const d=distance(centers[i],centers[j]);
                if(d>maxDist){maxDist=d; pair=[i,j];}
            }
        }
        spawnPoints=[];
        [pair[0],pair[1]].forEach(idx=>{
            const r=rooms[idx];
            const sx=randInt(r.x, r.x+r.w-1);
            const sy=randInt(r.y, r.y+r.h-1);
            spawnPoints.push({x:sx,y:sy});
        weapon
        weaponPoints=[];
        let tries=0;
        while(weaponPoints.length<WEAPON_COUNT && tries<100){
            const x=randInt(0,MAP_CELLS-1);
            const y=randInt(0,MAP_CELLS-1);
            if(map[x][y]===1 && !spawnPoints.some(p=>p.x===x&&p.y===y) && !weaponPoints.some(p=>p.x===x&&p.y===y)){
                weaponPoints.push({x,y});
            }
            tries++;
        }
        // connectivity check
        const reachable = floodFill(map,spawnPoints[0].x,spawnPoints[0].y);
        let allReachable=true;
        for(let i=0;i<MAP_CELLS && allReachable;i++){
            for(let j=0;j<MAP_CELLS;j++){
                if(map[i][j]===1 && !reachable[i][j]){allReachable=false;break;}
            }
        }
        if(allReachable)break;
        attempt++;
    }

    // ----- drawing -----
    ctx.clearRect(0,0,canvas.width,canvas.height);
    for(let i=0;i<MAP_CELLS;i++){
        for(let j=0;j<MAP_CELLS;j++){
            ctx.fillStyle = map[i][j]===0 ? '#000' : '#777';
            ctx.fillRect(i*CELL_SIZE, j*CELL_SIZE, CELL_SIZE, CELL_SIZE);
        }
    }
    // spawns
    spawnPoints.forEach(p=>{
        ctx.fillStyle='#0f0';
        ctx.fillRect(p.x*CELL_SIZE, p.y*CELL_SIZE, CELL_SIZE, CELL_SIZE);
    });
    // weapons
    weaponPoints.forEach(p=>{
        ctx.fillStyle='#f00';
        ctx.fillRect(p.x*CELL_SIZE, p.y*CELL_SIZE, CELL_SIZE, CELL_SIZE);
    });
    // ----- legend & button -----
    // legend container
    let legend=document.getElementById('fpsMapLegend');
    if(!legend){
        legend=document.createElement('div');
        legend.id='fpsMapLegend';
        legend.style.position='absolute';
        legend.style.left=canvas.offsetLeft+canvas.width+10+'px';
        legend.style.top=canvas.offsetTop+'px';
        legend.style.fontFamily='sans-serif';
        legend.style.fontSize='14px';
        legend.style.lineHeight='1.5';
        document.body.appendChild(legend);
    }
    legend.innerHTML=`<div><span style="display:inline-block;width:12px;height:12px;background:#000;margin-right:4px;"></span>Wall</div>
<div><span style="display:inline-block;width:12px;height:12px;background:#777;margin-right:4px;"></span>Floor</div>
<div><span style="display:inline-block;width:12px;height:12px;background:#0f0;margin-right:4px;"></span>Spawn Point</div>
<div><span style="display:inline-block;width:12px;height:12px;background:#f00;margin-right:4px;"></span>Weapon Pickup</div>`;
    // button
    let btn=document.getElementById('fpsMapBtn');
    if(!btn){
        btn=document.createElement('button');
        btn.id='fpsMapBtn';
        btn.textContent='Generate New Map';
        btn.style.display='block';
        btn.style.marginTop='10px';
        btn.onclick=()=>generateFPSMap(canvasId);
        legend.appendChild(btn);
    }
}

// auto-generate on load if a canvas with id 'gameCanvas' exists
window.addEventListener('load',()=>{if(document.getElementById('gameCanvas'))generateFPSMap('gameCanvas');});

